'AC-reporting.cash-flow.1'; from decimal import Decimal; import pytest; from src.reporting.base.cash_flow_calculator import calculate_cash_flow_bridge; pytestmark = pytest.mark.no_db
def test_standard_cash_flow_reconciles(): 'AC-reporting.cash-flow.1'; bridge = calculate_cash_flow_bridge(beginning_cash=Decimal('10000.00'), ending_cash=Decimal('11500.00'), operating_total=Decimal('3000.00'), investing_total=Decimal('-1000.00'), financing_total=Decimal('-500.00')); assert bridge.classified_activity == Decimal('1500.00'); assert bridge.cash_delta == Decimal('1500.00'); assert bridge.net_cash_flow == Decimal('1500.00'); assert bridge.fx_effect == Decimal('0.00'); assert bridge.discrepancy == Decimal('0.00'); assert bridge.reconciles is True; 'AC-reporting.cash-flow.1'; 'AC-reporting.cash-flow.1'; _m1_bridge = calculate_cash_flow_bridge(beginning_cash=Decimal('5000.00'), ending_cash=Decimal('7200.00'), operating_total=Decimal('2000.00'), investing_total=Decimal('0.00'), financing_total=Decimal('0.00'), fx_effect=Decimal('200.00')); assert _m1_bridge.cash_delta == Decimal('2200.00'); assert _m1_bridge.classified_activity == Decimal('2000.00'); assert _m1_bridge.fx_effect == Decimal('200.00'); assert _m1_bridge.bridge_total == Decimal('2200.00'); assert _m1_bridge.discrepancy == Decimal('0.00'); assert _m1_bridge.reconciles is True; 'AC-reporting.cash-flow.1'; 'AC-reporting.cash-flow.1'; _m2_bridge = calculate_cash_flow_bridge(beginning_cash=Decimal('0.00'), ending_cash=Decimal('10000.00'), operating_total=Decimal('0.00'), investing_total=Decimal('0.00'), financing_total=Decimal('0.00'), opening_stock_adjustment=Decimal('10000.00')); assert _m2_bridge.cash_delta == Decimal('10000.00'); assert _m2_bridge.net_cash_flow == Decimal('0.00'); assert _m2_bridge.reconciles is True; _m3_bridge = calculate_cash_flow_bridge(beginning_cash=Decimal('10000.00'), ending_cash=Decimal('15000.00'), operating_total=Decimal('4000.00'), investing_total=Decimal('0.00'), financing_total=Decimal('0.00')); assert _m3_bridge.cash_delta == Decimal('5000.00'); assert _m3_bridge.bridge_total == Decimal('4000.00'); assert _m3_bridge.discrepancy == Decimal('1000.00'); assert _m3_bridge.reconciles is False
